type IconName = keyof typeof icons;

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const Icon = ({ name, ...props }: { name: IconName | string;[key: string]: any }) => {
    const Component = (icons[name as IconName] || Fragment) as React.FC<React.SVGProps<SVGSVGElement>>;
    return (
        <Component {...props} />
    );
};

export default Icon;